import math

def normal_cdf(x):
    return 0.5*math.erfc(-x/math.sqrt(2.0))

def european_pair(spot,strike,rate,years,vol):
    # No dividends,European exercise,continuous annual rate and annualized vol.
    for value,low,high in ((spot,1.0,10000.0),(strike,1.0,10000.0),(rate,-0.2,0.5),(years,0.0,10.0),(vol,0.0,2.0)):
        if type(value) is not float or not math.isfinite(value) or not low<=value<=high:
            raise ValueError("invalid bounded pricing input")
    if years==0.0:return max(spot-strike,0.0),max(strike-spot,0.0)
    discounted_strike=strike*math.exp(-rate*years)
    if vol==0.0:return max(spot-discounted_strike,0.0),max(discounted_strike-spot,0.0)
    if years<1e-6 or vol<1e-6:
        raise ValueError("positive time/vol below teaching numerical domain")
    width=vol*math.sqrt(years)
    d1=(math.log(spot/strike)+(rate+0.5*vol*vol)*years)/width
    d2=d1-width
    if max(abs(d1),abs(d2))>8.0:
        raise ValueError("normal tail outside teaching numerical domain")
    # Compute the out-of-money side directly,then parity for the other side.
    if spot<=discounted_strike:
        call=spot*normal_cdf(d1)-discounted_strike*normal_cdf(d2)
        put=call+discounted_strike-spot
    else:
        put=discounted_strike*normal_cdf(-d2)-spot*normal_cdf(-d1)
        call=put+spot-discounted_strike
    return call,put

def call_greeks(spot,strike,rate,years,vol):
    european_pair(spot,strike,rate,years,vol) # same finite/range checks
    if years==0.0 or vol==0.0:raise ValueError("smooth Greeks require positive time and vol")
    root=math.sqrt(years)
    d1=(math.log(spot/strike)+(rate+0.5*vol*vol)*years)/(vol*root)
    d2=d1-vol*root
    density=math.exp(-0.5*d1*d1)/math.sqrt(2.0*math.pi)
    kd=strike*math.exp(-rate*years)
    return {"delta":normal_cdf(d1),"gamma":density/(spot*vol*root),
            "vega_per_1":spot*density*root,"rho_per_1":years*kd*normal_cdf(d2),
            "theta_per_year":-spot*density*vol/(2.0*root)-rate*kd*normal_cdf(d2)}

def price_risk_batch(requests):
    # Own schema:(version,kind,S,K,r,T,sigma,signed_underlying_units),USD only.
    if type(requests) is not list or len(requests)>16:raise ValueError("invalid batch")
    for req in requests:
        if type(req) is not tuple or len(req)!=8:raise ValueError("invalid request schema")
        version,kind,s,k,rate,t,v,units=req
        if type(version) is not int or version!=1 or type(kind) is not str or kind not in ("call","put"):
            raise ValueError("unsupported schema or kind")
        if type(units) is not float or not math.isfinite(units) or not -1000.0<=units<=1000.0:
            raise ValueError("invalid signed underlying units")
        european_pair(s,k,rate,t,v)
        if t==0.0 or v==0.0:raise ValueError("risk batch requires smooth positive time and vol")
    rows=[]
    for index,req in enumerate(requests):
        _,kind,s,k,rate,t,v,units=req
        prices=european_pair(s,k,rate,t,v)
        g=call_greeks(s,k,rate,t,v)
        if kind=="put":
            kd=k*math.exp(-rate*t)
            g["delta"]-=1.0
            g["rho_per_1"]-=t*kd
            g["theta_per_year"]+=rate*kd
        risk=tuple(units*g[key] for key in ("delta","gamma","vega_per_1","rho_per_1","theta_per_year"))
        price=prices[0 if kind=="call" else 1]
        rows.append((index,kind,price,units*price,risk))
    totals=(math.fsum(row[3] for row in rows),tuple(math.fsum(row[4][j] for row in rows) for j in range(5)))
    return "BS-NODIV-EU-v1","USD",tuple(rows),totals

batch=[(1,"call",100.0,100.0,0.05,1.0,0.2,100.0),(1,"put",100.0,100.0,0.05,1.0,0.2,-100.0)]
model,currency,rows,totals=price_risk_batch(batch)
print(model,currency)
print(f"value={totals[0]:.6f}")
print("risks",tuple(round(x,6) for x in totals[1]))
print(price_risk_batch([])[3])
try:price_risk_batch(batch+[(1,"call",100.0,100.0,0.05,0.0,0.2,1.0)])
except ValueError as error:print(error)
